<script setup lang="ts">
// generated by AI (GitHub Copilot, DeepSeek V4 Flash Vision Exp)
// Download the active encrypted database file for backup (nothing is
// decrypted here).

import { t } from '@nextcloud/l10n';

import { getDb } from '../storage/remote';
import { activeDescriptor } from '../state/session';
import { notify } from './notify';

async function exportCopy(): Promise<void> {
  const descriptor = activeDescriptor.value;
  if (!descriptor || descriptor.id === '') {
    notify(t('upm', 'Save the database before exporting it.'));
    return;
  }

  const bytes = await getDb(descriptor);
  if (bytes === null) {
    notify(t('upm', 'The database file is no longer available.'));
    return;
  }

  const blob = new Blob([bytes], { type: 'application/octet-stream' });
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = descriptor.path.split('/').pop() ?? 'upm.db';
  document.body.appendChild(link);
  link.click();
  link.remove();
  URL.revokeObjectURL(url);
}
</script>

<template>
  <button type="button" class="button" @click="exportCopy">
    {{ t('upm', 'Export encrypted copy') }}
  </button>
</template>
